var UIWORDS={"Preset": {"name": "Preset", "text": "A wall to start from: a state of the controls named after a reference photo or a form. Picking one sets every control of the four panels (not Scale, seed, Quality or the view). Walls marked \"refuses\" are meant to fail the gate, so that you can see it. The badge \"gate 5/6\" counts the draft builds of that wall (3 seeds, both scales) that pass the gate with the bridge faces counted apart; they come from the sweep that wrote this page.", "step": "a-viewer", "panel": "ui"}, "Scale": {"name": "Scale", "text": "The size of a square: 35 mm (DungeonBlocks) or 25.4 mm (OpenLOCK). Every length scales with it; the line a printer lays down does not.", "step": "a-footprint", "panel": "ui"}, "seed": {"name": "seed", "text": "The number every random draw starts from. The same seed makes the same wall.", "step": "a-viewer", "panel": "ui"}, "Quality": {"name": "Quality", "text": "The resolution the whole build is made at: the rock is meshed at draft (coarse, fast) or fine (what a print would use), and every stone changes with it. The union and the gate are exact and have no resolution of their own. It is part of the spec header.", "step": "a-weather", "panel": "ui"}, "RockPreset": {"name": "Rock preset", "text": "A named set of values for the Rock panel's controls, from the same table as the Weathered Stone page (the shape and size controls are the wall's, so a rock preset leaves them). Choosing one replaces the whole Rock panel; the changes you make afterwards are marked against it. Choosing a wall preset again resets everything.", "step": "a-weather", "panel": "ui"}, "View": {"name": "View", "text": "How the model is painted: shaded, by overhang angle, dry brushed, or as the slices a slicer lays down.", "step": "a-union", "panel": "ui"}, "view-shaded": {"name": "Shaded", "text": "Plain grey shading.", "step": "a-union", "panel": "ui"}, "view-over": {"name": "Overhang", "text": "Paints every face by how far it leans out: orange from 55 to 65 degrees, red beyond 65.", "step": "a-union", "panel": "ui"}, "view-brush": {"name": "Dry brush", "text": "A dark undercoat with a light coat on what looks up and on every worn edge.", "step": "a-union", "panel": "ui"}, "view-lines": {"name": "Lines", "text": "Shows the layers and the section a slicer would see.", "step": "a-union", "panel": "ui"}, "Target": {"name": "Target", "text": "Draws the box the wall aims for: the footprint on the ground and the crest height above it.", "step": "a-footprint", "panel": "ui"}, "Rows": {"name": "Rows", "text": "Draws the row planes the stones stand between, so you can read each stone against them.", "step": "a-planes", "panel": "ui"}, "Projection": {"name": "Projection", "text": "Perspective looks like a camera; orthographic keeps parallel lines parallel. The model is the same.", "step": "a-viewer", "panel": "ui"}, "Level": {"name": "Level", "text": "How many steps of the build are shown, from the footprint (L0) to the joined body the gate judges (L5). Opening a panel moves it to the step that shows that panel.", "step": "a-viewer", "panel": "ui"}, "level-0": {"name": "L0 footprint", "text": "Only the box the wall aims for: where it stands and how high.", "step": "a-footprint", "panel": "ui"}, "level-1": {"name": "L1 row planes", "text": "The row planes, fixed for the whole wall before any stone exists.", "step": "a-planes", "panel": "ui"}, "level-2": {"name": "L2 blocks", "text": "Every stone as a plain prism: its base area between its two planes.", "step": "a-build", "panel": "ui"}, "level-3": {"name": "L3 joints", "text": "Marks which faces of a stone are joints and which neighbours merged. Nothing is cut yet.", "step": "a-joints", "panel": "ui"}, "level-4": {"name": "L4 the rock", "text": "Every stone becomes the rock: its cell, weathered by the six stages. Drawn as the cells first, then each stone as it is built.", "step": "a-weather", "panel": "ui"}, "v-3d": {"name": "3D", "text": "The model in three dimensions. Drag to turn it.", "step": "a-viewer", "panel": "ui"}, "v-plan": {"name": "Plan", "text": "The wall seen from above: course 0 solid, course 1 dashed, course 2 dotted.", "step": "a-subdivide", "panel": "ui"}, "v-elev": {"name": "Elevation", "text": "The wall seen from the front, every face of every block.", "step": "a-build", "panel": "ui"}, "v-costs": {"name": "Costs", "text": "The time, triangles and memory of this build, step by step, and every number the gate reads.", "step": "a-union", "panel": "ui"}, "zoom": {"name": "zoom", "text": "Makes the view bigger or smaller. Works in every view.", "step": "a-viewer", "panel": "ui"}, "reset": {"name": "reset view", "text": "Returns the camera and the zoom to where they started.", "step": "a-viewer", "panel": "ui"}, "gate": {"name": "Build", "text": "The state of the build: a spinner while the stones are built, then green if the wall passes the gate and red if it fails. Tap it for the record: every step in build order with its time and count, and the gate both ways (as it counts, and with the bridge faces counted apart).", "step": "a-union", "panel": "ui"}, "ViewOptions": {"name": "View options", "text": "Opens the view controls: how the model is painted, the target and the rows, and the projection. They change what you see, never the model.", "step": "a-viewer", "panel": "ui"}, "CopySpec": {"name": "Copy spec", "text": "Copies everything needed to rebuild what you see, as plain text: the build, the preset, scale and seed, every control grouped by panel with what differs from the preset marked, stage switches and Solo, the view, and then the result (the gate both ways, triangles, stones, times) and any problems the page caught. The same box loads a pasted spec back.", "step": "a-viewer", "panel": "ui"}, "Maximize": {"name": "Maximize", "text": "Makes the viewer cover the whole page, so you can look closer. The same button, or Escape, brings it back; the camera, the build and everything open stay as they are.", "step": "a-viewer", "panel": "ui"}, "Measure": {"name": "Measure", "text": "The page's measuring tools: the union by four routes, and the history of the last builds. They read the build; they change nothing.", "step": "a-union", "panel": "ui"}, "level-5": {"name": "L5 union", "text": "Joins everything into one body, which is what the gate judges.", "step": "a-union", "panel": "ui"}};
/* the pop-up table: one entry for every row, group and viewer control, read by popups.js */
var CTL=(function(){var t={};ROWS.forEach(function(r){t[r.ctl]={name:r.name,text:r.text,step:r.stepid,panel:r.panel}});Object.keys(UIWORDS).forEach(function(k){t[k]=UIWORDS[k]});GROUPS.forEach(function(g){t['group-'+g.id]={name:g.title,text:g.line,step:g.stepid}});
  [{id:'region',s:'a-footprint'},{id:'courses',s:'a-planes'},{id:'rockregion',s:'a-outline'},{id:'rock',s:'a-weather'}].forEach(function(p){var P=PANELS.filter(function(x){return x.id===p.id})[0];t['panel-'+p.id]={name:P.title,text:P.line,step:p.s}});
  t['Solo']={name:'Solo',text:'Shows only this stage: every other stage is off, so you can see what it does alone.',step:'a-weather'};t['On']={name:'On or off',text:'Turns a stage on or off. At strength 0 a stage changes nothing, byte for byte.',step:'a-weather'};return t})();
/* the dials, in the shape the word table and the step lists read: [key, label, kind, min, max, step, unit, panel] */
var DIALS=ROWS.filter(function(r){return r.kind==='num'||r.kind==='range'}).map(function(r){return [r.ctl,r.label,r.kind==='range'?'rng':'num',r.min,r.max,r.step,r.unit,r.panel]});
/* every control in the page must have a row, and every row must point at a step that exists; both are reported loudly */
function checkControls(root){var bad=[];[].forEach.call((root||document).querySelectorAll('[data-ctl]'),function(e){var k=e.getAttribute('data-ctl');if(!CTL[k])bad.push('control with no row in the table: '+k)});
  Object.keys(CTL).forEach(function(k){var s=CTL[k].step;if(!STEPS[s])bad.push('row '+k+' points at a step with no title: '+s);if(!document.getElementById(s))bad.push('row '+k+' points at a step that is not in the page: '+s)});
  bad.forEach(function(m){console.error('[controls] '+m)});window.__ctlErrors=bad;return bad}
